/**
 * The Graph page of a repository: a navigation GET serves the Workbench shell, a page-data GET the page model, and a
 * POST runs one SPARQL SELECT, CONSTRUCT or DESCRIBE query for the browser-side graph explorer and streams the result
 * as SPARQL Results JSON (statements of a graph query as {@code ?source ?predicate ?target} solutions). The query text
 * arrives either as an {@code application/sparql-query} body or as the form parameter {@code query}.
 */
public class GraphServlet extends TransformationServlet {

	/** Init parameter naming the maximum accepted query length in characters. */
	public static final String MAX_QUERY_LENGTH_PARAM = "graph-max-query-length";

	public static final int DEFAULT_MAX_QUERY_LENGTH = 150_000;

	private static final String SPARQL_QUERY_CONTENT_TYPE = "application/sparql-query";

	private static final String SPARQL_RESULTS_JSON = "application/sparql-results+json";

	private static final String QUERY_EXECUTION_FEATURE = "query-execution";

	private int maxQueryLength = DEFAULT_MAX_QUERY_LENGTH;

	@Override
	public void init(ServletConfig config) throws ServletException {
		super.init(config);
		String configured = config.getInitParameter(MAX_QUERY_LENGTH_PARAM);
		if (configured != null && !configured.isBlank()) {
			try {
				maxQueryLength = Integer.parseInt(configured.trim());
			} catch (NumberFormatException e) {
				throw new ServletException(MAX_QUERY_LENGTH_PARAM + " must be an integer: " + configured, e);
			}
			if (maxQueryLength <= 0) {
				throw new ServletException(MAX_QUERY_LENGTH_PARAM + " must be positive: " + configured);
			}
		}
	}

	@Override
	public String[] getCookieNames() {
		return new String[] { "infer", "query-timeout" };
	}

	/** The page model: who the repository is and what the explorer may send. */
	@Override
	protected void service(WorkbenchRequest req, HttpServletResponse resp) throws Exception {
		TupleResultBuilder builder = getTupleResultBuilder(req, resp, resp.getOutputStream());
		builder.start("id", "readable", "writeable", "max-query-length");
		builder.link(List.of(INFO));
		builder.result(info.getId(), info.isReadable(), info.isWritable(), maxQueryLength);
		builder.end();
	}

	@Override
	protected void doPost(WorkbenchRequest req, HttpServletResponse resp) throws Exception {
		String queryText = readQuery(req);
		if (queryText == null || queryText.isBlank()) {
			reject(resp, HttpServletResponse.SC_BAD_REQUEST,
					"A SPARQL SELECT, CONSTRUCT or DESCRIBE query is required.");
			return;
		}
		if (queryText.length() > maxQueryLength) {
			reject(resp, HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE,
					"The query exceeds the maximum of " + maxQueryLength + " characters.");
			return;
		}
		if (!isQueryExecutionEnabled()) {
			resp.sendError(HttpServletResponse.SC_FORBIDDEN);
			return;
		}
		ParsedQuery parsed;
		try {
			parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, queryText, null);
		} catch (MalformedQueryException e) {
			reject(resp, HttpServletResponse.SC_BAD_REQUEST, "Malformed query: " + e.getMessage());
			return;
		}
		if (!(parsed instanceof ParsedTupleQuery) && !(parsed instanceof ParsedGraphQuery)) {
			reject(resp, HttpServletResponse.SC_BAD_REQUEST,
					"The graph explorer runs SELECT, CONSTRUCT or DESCRIBE queries.");
			return;
		}
		try (RepositoryConnection connection = repository.getConnection()) {
			Query query = parsed instanceof ParsedGraphQuery
					? connection.prepareGraphQuery(QueryLanguage.SPARQL, queryText)
					: connection.prepareTupleQuery(QueryLanguage.SPARQL, queryText);
			query.setIncludeInferred(includeInferred(req));
			int timeout = queryTimeout(req);
			if (timeout > 0) {
				query.setMaxExecutionTime(timeout);
			}
			resp.setStatus(HttpServletResponse.SC_OK);
			resp.setContentType(SPARQL_RESULTS_JSON);
			resp.setCharacterEncoding(StandardCharsets.UTF_8.name());
			resp.setHeader("Cache-Control", "no-store");
			SPARQLResultsJSONWriter writer = new SPARQLResultsJSONWriter(resp.getOutputStream());
			long limit = rowLimit(req);
			if (query instanceof GraphQuery graphQuery) {
				writeStatements(graphQuery, writer, limit);
			} else {
				writeSolutions((TupleQuery) query, writer, limit);
			}
		}
	}

	/**
	 * A CONSTRUCT or DESCRIBE result in the same SPARQL Results JSON the explorer reads for SELECT: one solution per
	 * statement, binding {@code source}, {@code predicate} and {@code target}.
	 */
	private static void writeStatements(GraphQuery query, SPARQLResultsJSONWriter writer, long limit) {
		List<String> names = List.of("source", "predicate", "target");
		writer.startQueryResult(names);
		long written = 0;
		try (GraphQueryResult statements = query.evaluate()) {
			while (statements.hasNext() && written++ < limit) {
				Statement statement = statements.next();
				writer.handleSolution(new ListBindingSet(names, statement.getSubject(), statement.getPredicate(),
						statement.getObject()));
			}
		}
		writer.endQueryResult();
	}

	/** A SELECT result, at most {@code limit} solutions of it. */
	private static void writeSolutions(TupleQuery query, SPARQLResultsJSONWriter writer, long limit) {
		try (TupleQueryResult solutions = query.evaluate()) {
			writer.startQueryResult(solutions.getBindingNames());
			long written = 0;
			while (solutions.hasNext() && written++ < limit) {
				writer.handleSolution(solutions.next());
			}
		}
		writer.endQueryResult();
	}

	/**
	 * The {@code row-limit} parameter: how many rows the page wants at most (queries other Workbench pages handed over
	 * have no LIMIT of their own). Anything but a positive number means no limit. It is read from the request itself:
	 * {@link WorkbenchRequest#getParameter(String)} falls back to cookies and Workbench defaults, and the Query page's
	 * page size lives in a "limit" cookie.
	 */
	private static long rowLimit(WorkbenchRequest req) {
		String limit = req.getRequest().getParameter("row-limit");
		if (limit == null || limit.isBlank()) {
			return Long.MAX_VALUE;
		}
		try {
			long value = Long.parseLong(limit.trim());
			return value > 0 ? value : Long.MAX_VALUE;
		} catch (NumberFormatException e) {
			return Long.MAX_VALUE;
		}
	}

	private static String readQuery(WorkbenchRequest req) throws IOException {
		String contentType = req.getContentType();
		if (contentType != null && contentType.toLowerCase(Locale.ENGLISH).startsWith(SPARQL_QUERY_CONTENT_TYPE)) {
			return new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
		}
		return req.getParameter("query");
	}

	private static boolean includeInferred(WorkbenchRequest req) {
		String infer = req.getParameter("infer");
		return infer == null || infer.isBlank() || Boolean.parseBoolean(infer);
	}

	private static int queryTimeout(WorkbenchRequest req) {
		String timeout = req.getParameter("query-timeout");
		if (timeout == null || timeout.isBlank()) {
			return 0;
		}
		try {
			return Integer.parseInt(timeout.trim());
		} catch (NumberFormatException e) {
			return 0;
		}
	}

	private static void reject(HttpServletResponse resp, int status, String message) throws IOException {
		resp.setStatus(status);
		resp.setContentType(TEXT_PLAIN);
		resp.setCharacterEncoding(StandardCharsets.UTF_8.name());
		resp.getWriter().write(message);
	}

	private boolean isQueryExecutionEnabled() {
		WorkbenchPolicy policy = getWorkbenchPolicy();
		return policy == null || policy.isQueryFeatureEnabled(QUERY_EXECUTION_FEATURE);
	}

	/** The deployment policy, or {@code null} when none can be loaded (tests without a servlet context). */
	protected WorkbenchPolicy getWorkbenchPolicy() {
		if (config == null) {
			return null;
		}
		try {
			return WorkbenchPolicyLoader.getPolicy(config.getServletContext(), appConfig);
		} catch (ServletException e) {
			return null;
		}
	}
}
